from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:

        @lru_cache(None)
        def count_ways_sum(rem: int, rem_sum: int) -> int:
            if rem_sum < 0:
                return 0
            if rem == 0:
                return int(rem_sum == 0)
            ans = 0
            for d in range(10):
                if rem_sum - d >= 0:
                    ans += count_ways_sum(rem - 1, rem_sum - d)
            return ans

        @lru_cache(None)
        def solve_free(rem: int, cur_sum: int, prod_mod: int, started: bool, target_sum: int) -> int:
            if cur_sum > target_sum:
                return 0
            if rem == 0:
                return int(started and cur_sum == target_sum and prod_mod == 0)

            # Optimization: Once the product is 0 (or a multiple of target_sum), 
            # ANY completion that correctly achieves the target sum will be beautiful.
            if started and prod_mod == 0:
                return count_ways_sum(rem, target_sum - cur_sum)

            ans = 0
            for d in range(10):
                if not started and d == 0:
                    # Trailing leading zeros
                    ans += solve_free(rem - 1, cur_sum, 1 % target_sum, False, target_sum)
                else:
                    if cur_sum + d <= target_sum:
                        next_prod = (prod_mod * d) % target_sum
                        ans += solve_free(rem - 1, cur_sum + d, next_prod, True, target_sum)
            return ans

        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            max_sum = 9 * len(digits)
            total = 0

            for target_sum in range(1, max_sum + 1):
                def dp_tight(pos: int, cur_sum: int, prod_mod: int, tight: bool, started: bool) -> int:
                    if cur_sum > target_sum:
                        return 0

                    rem = len(digits) - pos
                    if not tight:
                        return solve_free(rem, cur_sum, prod_mod, started, target_sum)

                    if rem == 0:
                        return int(started and cur_sum == target_sum and prod_mod == 0)

                    limit = digits[pos]
                    ans = 0
                    for d in range(limit + 1):
                        is_next_tight = (d == limit)

                        if not started and d == 0:
                            ans += dp_tight(pos + 1, cur_sum, 1 % target_sum, is_next_tight, False)
                        else:
                            if cur_sum + d <= target_sum:
                                next_prod = (prod_mod * d) % target_sum
                                ans += dp_tight(pos + 1, cur_sum + d, next_prod, is_next_tight, True)
                    return ans

                total += dp_tight(0, 0, 1 % target_sum, True, False)
            return total

        return count_up_to(r) - count_up_to(l - 1)
